            position: absolute;
            pointer-events: none;
            /* Used by JS to overlay the aiming line */
        }
    </style>
</head>
<body>

    <h1>Billiards Physics Simulation</h1>
    <div id="instructions">
        <h2>Instructions</h2>
        <p><strong>Aiming:</strong> Press down on the white cue ball, drag back (opposite direction of desired shot), and release. The longer you drag, the harder the hit.</p>
        <p><strong>Controls:</strong> Click 'Reset/Rack' to start a new game or use buttons below.</p>
    </div>

    <div id="gameContainer">
        <canvas id="billiardsCanvas" width="900" height="500"></canvas>

        <div id="controls">
            <h3>Game Controls</h3>
            <div>
                <button id="resetButton">Reset / Rack Balls</button>
            </div>
            <div>
                <p id="status">Status: Ready.</p>
                <button id="pauseResumeButton" disabled>Pause</button>
            </div>
        </div>
    </div>

<script>
// ==============================================
// GLOBAL CONSTANTS AND SETUP
// ==============================================

const canvas = document.getElementById('billiardsCanvas');
const ctx = canvas.getContext('2d');

window.sim = {}; // The required global simulation object

// Physical constants
const FRICTION_COEFF = 0.998; // Speed decay factor per step
const RESTITUTION_COEFF = 1.0; // Elastic collisions (near-perfect)
const POCKETS = [
    {x: 50, y: 50, r: 20},   // Top Left Corner Pocket
    {x: canvas.width - 50, y: 50, r: 20}, // Top Right Corner Pocket
    {x: 50, y: canvas.height - 50, r: 20}, // Bottom Left Corner Pocket
    {x: canvas.width - 50, y: canvas.height - 50, r: 20}, // Bottom Right Corner Pocket
    {x: Math.floor(canvas.width / 2), y: 100, r: 30}, // Center Top Pocket (Long rail)
    {x: Math.floor(canvas.width / 2), y: canvas.height - 100, r: 30}  // Center Bottom Pocket (Long rail)
];

window.sim.W = canvas.width;
window.sim.H = canvas.height;
window.sim.R = 8; // Ball radius in pixels

let balls = [];
let animationFrameId = null;
let gameIsRunning = false;

// Aiming state variables
let isAiming = false;
let aimStartMousePos = {x: 0, y: 0};
let aimCurrentMousePos = {x: 0, y: 0};
let cueBallIndex = -1; // Index of the white ball

// Utility function to calculate distance squared
const distSq = (p1, p2) => (p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y);

// Helper to initialize ball state
function createBall(x, y, vx = 0, vy = 0, cue = false) {
    return { x: x, y: y, vx: vx, vy: vy, potted: false, cue: cue };
}


/**
 * PHYSICS IMPLEMENTATION
 */

// 1. Handle Wall Collisions (Cushions)
function handleWallCollisions() {
    for (let i = 0; i < balls.length; i++) {
        const ball = balls[i];

        if (ball.potted) continue;

        // Left/Right Walls
        if (ball.x - window.sim.R < 1 || ball.x + window.sim.R > window.sim.W - 1) {
            ball.vx = -Math.abs(ball.vx); // Reflect X velocity
        }
        // Top/Bottom Walls
        if (ball.y - window.sim.R < 1 || ball.y + window.sim.R > window.sim.H - 1) {
            ball.vy = -Math.abs(ball.vy); // Reflect Y velocity
        }

        // Keep balls constrained within the effective playing area (minus cushion thickness, handled by canvas size/rails drawing)
    }
}


// 2. Handle Pocketing
function handlePocketing() {
    for (let i = 0; i < balls.length; i++) {
        const ball = balls[i];

        if (ball.potted) continue;

        for (const pocket of POCKETS) {
            // Check if the center of the ball is within a small radius of a corner/center pocket location
            if (!ball.potted && distSq(ball, pocket) < Math.pow(pocket.r + window.sim.R * 0.8, 2)) {
                // If it gets close enough to a designated pocket center AND the ball is slowing down (to prevent immediate potting on impact)
                if (Math.abs(ball.vx) < 1 && Math.abs(ball.vy) < 1) {
                    ball.potted = true;
                    // Stop movement completely when potted
                    ball.vx = 0;
                    ball.vy = 0;
                    break; // Found a pocket, no need to check other pockets
                }
            }
        }
    }
}

// 3. Handle Ball-to-Ball Collisions
function handleCollisions(dt) {
    const numBalls = balls.length;
    let collided = false;

    for (let i = 0; i < numBalls; i++) {
        for (let j = i + 1; j < numBalls; j++) {
            const ballA = balls[i];
            const ballB = balls[j];

            if (ballA.potted || ballB.potted) continue;

            // Check for overlap/collision detection
            const dx = ballB.x - ballA.x;
            const dy = ballB.y - ballA.y;
            const distSq_check = dx * dx + dy * dy;
            const minDistance = 2 * window.sim.R;
            const minDistanceSq = minDistance * minDistance;

            if (distSq_check < minDistanceSq) {
                collided = true;

                // Calculate overlap depth and penetration vector
                const distance = Math.sqrt(distSq_check);
                const overlap = minDistance - distance;

                // 1. Separation/Position Correction (Push them apart first)
                const nx = dx / distance; // Normal vector X
                const ny = dy / distance; // Normal vector Y

                // Move balls proportionally to the overlap amount
                ballA.x -= nx * overlap * 0.5;
                ballA.y -= ny * overlap * 0.5;
                ballB.x += nx * overlap * 0.5;
                ballB.y += ny * overlap * 0.5;

                // 2. Velocity Resolution (Impulse calculation)
                const relativeVdx = ballB.vx - ballA.vx;
                const relativeVdy = ballB.vy - ballA.vy;

                // Calculate the velocity component along the normal vector (relative velocity projected onto collision line)
                const velocityAlongNormal = relativeVdx * nx + relativeVdy * ny;

                // If balls are already moving away, skip resolution to prevent jitter/explosion
                if (velocityAlongNormal > 0) continue;

                // Calculate impulse magnitude (J) using the coefficient of restitution (e=1 for elastic)
                const j = -(1 + RESTITUTION_COEFF) * velocityAlongNormal / (1/1 + 1/1); // Since masses are equal (m=1)

                // Apply impulses
                ballA.vx -= j * nx;
                ballA.vy -= j * ny;

                ballB.vx += j * nx;
                ballB.vy += j * ny;

                // Dampen speeds slightly after collision to account for energy loss/simulation noise
                ballA.vx *= 0.95; ballA.vy *= 0.95;
                ballB.vx *= 0.95; ballB.vy *= 0.95;

            }
        }
    }
    return collided;
}


/**
 * MAIN PHYSICS STEP FUNCTION
 */

// Advances the state of all balls by dt seconds.
function physicsStep(dt) {
    for (let i = 0; i < balls.length; i++) {
        const ball = balls[i];

        if (ball.potted) {
            continue; // Ignore potted balls
        }

        // 1. Apply Friction/Damping
        ball.vx *= FRICTION_COEFF;
        ball.vy *= FRICTION_COEFF;

        // Simple drag limit: if speed is tiny, stop it.
        if (Math.abs(ball.vx) < 0.1 && Math.abs(ball.vy) < 0.1) {
            ball.vx = 0;
            ball.vy = 0;
        }

        // 2. Update Position
        ball.x += ball.vx * dt;
        ball.y += ball.vy * dt;
    }

    handleWallCollisions(); // Reflects off walls/cushions
    handlePocketing();     // Checks for pot status
    handleCollisions(dt);  // Resolves inter-ball collisions
}


/**
 * RENDERING FUNCTIONS
 */

function drawTable() {
    // Draw felt surface (already set in CSS background, but we redraw the boundaries)
    ctx.fillStyle = '#1e6a3f'; // Felt Green
    ctx.fillRect(0, 0, window.sim.W, window.sim.H);

    // Draw rails and cushions (simulate wood frame)
    ctx.strokeStyle = '#8B4513';
    ctx.lineWidth = 8; // Thickness of the cushion/rail visible edge
    ctx.strokeRect(0, 0, window.sim.W, window.sim.H);

    // Draw pockets (visible openings)
    ctx.fillStyle = '#000000'; // Black pocket background
    POCKETS.forEach(pocket => {
        ctx.beginPath();
        ctx.arc(pocket.x, pocket.y, pocket.r, 0, Math.PI * 2);
        ctx.fill();
    });

    // Draw a subtle centerline marker (optional visual flair)
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.1)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(window.sim.W / 2, 0);
    ctx.lineTo(window.sim.W / 2, window.sim.H);
    ctx.stroke();
}

function drawAimLine(startX, startY, endX, endY) {
    // The aim line is drawn *over* the canvas when dragging
    const length = Math.sqrt((endX - startX)**2 + (endY - startY)**2);
    if (length < 5) return;

    ctx.strokeStyle = 'rgba(255, 255, 0, 0.8)'; // Yellow line for aiming
    ctx.lineWidth = 3;
    ctx.lineCap = 'round';

    // Draw the line segment representing direction
    ctx.beginPath();
    ctx.moveTo(startX, startY);
    ctx.lineTo(endX, endY);
    ctx.stroke();
}


function drawBalls() {
    for (const ball of balls) {
        if (!ball.potted && ball.vx !== 0 || !ball.potted && ball.vy !== 0) {
            // Draw a faint trail or indication of movement
        }

        ctx.beginPath();
        ctx.arc(ball.x, ball.y, window.sim.R, 0, Math.PI * 2);

        if (ball.cue) {
            ctx.fillStyle = '#FFFFFF'; // White cue ball
            ctx.strokeStyle = '#333';
            ctx.lineWidth = 1;
        } else if (ball.potted) {
             // Potted balls are drawn slightly off screen/grayed out to indicate state change
             ctx.fillStyle = '#555';
             ctx.globalAlpha = 0.6;
        } else {
            const colorIndex = (balls.indexOf(ball) + 1) % 3;
            let color;
            if (colorIndex === 0) color = 'red';
            else if (colorIndex === 1) color = 'blue';
            else color = '#FFD700'; // Gold/Yellow
            ctx.fillStyle = color;
        }

        // Draw the ball fill
        ctx.fill();

        // Add a simple highlight for shine
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.6)';
        ctx.lineWidth = 1.5;
        ctx.stroke();

        if (ball.potted) {
            ctx.globalAlpha = 1.0; // Reset alpha for clarity
        }
    }
    // Reset global alpha state after drawing balls
    ctx.globalAlpha = 1.0; 
}

function render() {
    // Clear the canvas
    ctx.clearRect(0, 0, window.sim.W, window.sim.H);

    drawTable();
    drawBalls();

    if (isAiming) {
        const cueBall = balls[cueBallIndex];
        if (cueBall) {
            // Draw the aim guide overlay if aiming is active
            ctx.save();
            // Calculate vector from center to mouse drag endpoint
            const dx_aim = aimCurrentMousePos.x - aimStartMousePos.x;
            const dy_aim = aimCurrentMousePos.y - aimStartMousePos.y;

            // The displayed aiming line should originate at the cue ball's current position
            ctx.beginPath();
            ctx.moveTo(cueBall.x, cueBall.y);
            ctx.lineTo(aimCurrentMousePos.x, aimCurrentMousePos.y);
            ctx.strokeStyle = 'rgba(255, 160, 0, 0.8)'; // Orange/Yellow for aiming guide
            ctx.lineWidth = 4;
            ctx.lineCap = 'round';
            ctx.stroke();

            // Optionally draw a dotted line showing the potential trajectory path
            const dragMagnitude = Math.sqrt(dx_aim * dx_aim + dy_aim * dy_aim);
            if (dragMagnitude > 1) {
                const angleRad = Math.atan2(dy_aim, dx_aim);
                // Show a short prediction line
                ctx.strokeStyle = 'rgba(0, 255, 0, 0.6)'; // Green predicted path
                ctx.beginPath();
                ctx.moveTo(cueBall.x + Math.cos(angleRad) * window.sim.R * 1.5, cueBall.y + Math.sin(angleRad) * window.sim.R * 1.5);
                ctx.lineTo(cueBall.x + Math.cos(angleRad) * (window.sim.R * 3), cueBall.y + Math.sin(angleRad) * (window.sim.R * 3));
                ctx.lineWidth = 2;
                ctx.stroke();
            }

            ctx.restore();
        }
    }
}


/**
 * CORE SIMULATION LOOP AND CONTROL LOGIC
 */

function gameLoop(timestamp) {
    if (!gameIsRunning) return;

    // Standard fixed step size for deterministic physics updates
    const dt = 1 / 60; // 60 FPS simulation steps

    // Run multiple physics steps if we missed frames, or just one for simple timing.
    physicsStep(dt); 
    render();

    animationFrameId = requestAnimationFrame(gameLoop);
}


/**
 * PUBLIC API Implementation (window.sim)
 */
window.sim = {
    // State accessors
    W: window.sim.W,
    H: window.sim.H,
    R: window.sim.R,

    reset: function(initialBalls = null) {
        // Clear existing state and physics
        balls = []; 
        gameIsRunning = false;

        if (initialBalls && initialBalls.length > 0) {
            // If provided external balls array, use it directly
            for (let i = 0; i < initialBalls.length; i++) {
                const b = initialBalls[i];
                balls.push(createBall(b.x, b.y, b.vx || 0, b.vy || 0, !!b.cue));
            }
        } else {
             // Default Rack Setup (14 balls)
            const rackConfig = [
                { x: window.sim.W * 0.25, y: window.sim.H * 0.75, cue: true }, // Cue Ball
                { x: window.sim.W * 0.35, y: window.sim.H * 0.60 }, // Ball 1
                { x: window.sim.W * 0.25, y: window.sim.H * 0.45 }, // Ball 2 (Top Left)

                // Middle Rack Row
                { x: window.sim.W * 0.15, y: window.sim.H * 0.35 }, // Ball 3
                { x: window.sim.W * 0.45, y: window.sim.H * 0.35 }, // Ball 4 (Center)
                { x: window.sim.W * 0.75, y: window.sim.H * 0.35 }, // Ball 5

                 // Next Row
                { x: window.sim.W * 0.15, y: window.sim.H * 0.25 }, // Ball 6
                { x: window.sim.W * 0.45, y: window.sim.H * 0.25 }, // Ball 7
                { x: window.sim.W * 0.75, y: window.sim.H * 0.25 }, // Ball 8

                 // Bottom Row (near the rails)
                { x: window.sim.W * 0.15, y: window.sim.H * 0.15 }, // Ball 9
                { x: window.sim.W * 0.45, y: window.sim.H * 0.15 }, // Ball 10
                { x: window.sim.W * 0.75, y: window.sim.H * 0.15 }, // Ball 11

                 // Corner Balls (for a full rack setup)
                { x: window.sim.W * 0.25, y: window.sim.H * 0.85 }, 
                { x: window.sim.W * 0.75, y: window.sim.H * 0.85 }
            ];

            for (const b of rackConfig) {
                balls.push(createBall(b.x, b.y, 0, 0, b.cue));
            }
        }

        // Ensure the cue ball is correctly identified after reset
        cueBallIndex = balls.findIndex(b => b.cue);

        console.log("Simulation Reset. Balls:", balls.length);
        updateStatus("Rack complete! Click 'Start Shot' or wait for auto-play.");
    },

    step: function(dt) {
        if (!gameIsRunning) return;
        physicsStep(dt);
        render();
    },

    state: function() {
        // Return a copy of the required state structure
        return balls.map(b => ({ 
            x: b.x, y: b.y, vx: b.vx, vy: b.vy, potted: b.potted, cue: b.cue 
        }));
    },

    shoot: function(vx, vy) {
        if (cueBallIndex === -1 || balls[cueBallIndex].potted) {
            console.error("Cannot shoot: Cue ball not found or potted.");
            return;
        }
        const cueBall = balls[cueBallIndex];

        // Apply shot velocity instantly to the cue ball
        cueBall.vx += vx;
        cueBall.vy += vy;

        updateStatus(`Shot fired! Velocity: (${Math.round(Math.abs(vx))}, ${Math.round(Math.abs(vy))})`);
    },

    pause: function() {
        if (animationFrameId) {
            cancelAnimationFrame(animationFrameId);
            gameIsRunning = false;
            document.getElementById('pauseResumeButton').textContent = 'Resume';
            updateStatus("Simulation Paused.");
        }
    },

    resume: function() {
        if (!gameIsRunning) {
             // Restart the loop if paused, maintaining the current animation frame context
            gameIsRunning = true; 
            document.getElementById('pauseResumeButton').textContent = 'Pause';
            requestAnimationFrame(gameLoop);
            updateStatus("Simulation Resumed.");
        }
    },

    /** Exposed for testing/initial setup */
    _start: function() {
        if (!gameIsRunning) {
             // Start the animation loop when the simulation object is first initialized.
            gameIsRunning = true;
            document.getElementById('pauseResumeButton').textContent = 'Pause';
            animationFrameId = requestAnimationFrame(gameLoop);
        }
    }
};


/**
 * INTERFACE HANDLERS (Mouse Input and Controls)
 */

// --- UI Status Update ---
function updateStatus(message, isError = false) {
    const statusElement = document.getElementById('status');
    statusElement.textContent = `Status: ${message}`;
    statusElement.style.color = isError ? 'red' : 'black';
}


// --- Mouse Input Logic (Aiming) ---

function getMousePos(e) {
    const rect = canvas.getBoundingClientRect();
    return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
    };
}

canvas.addEventListener('mousedown', (e) => {
    if (!gameIsRunning || balls[cueBallIndex]?.potted) return;
    const currentPos = getMousePos(e);

    // Check if the mouse is near the cue ball center
    const cueBall = balls[cueBallIndex];
    if (Math.sqrt((currentPos.x - cueBall.x)**2 + (currentPos.y - cueBall.y)**2) < 30) {
        isAiming = true;
        aimStartMousePos = currentPos;
        aimCurrentMousePos = currentPos;
        updateStatus("Aiming started. Drag back to set power.");
    } else {
        isAiming = false;
    }
});

canvas.addEventListener('mousemove', (e) => {
    if (!isAiming) return;
    aimCurrentMousePos = getMousePos(e);
    render(); // Re-render to show the aiming line
});

document.addEventListener('mouseup', (e) => {
    if (!isAiming || !balls[cueBallIndex]) return;

    const shotEndPos = getMousePos(e);

    // Calculate displacement vector: Shot is in the *opposite* direction of drag force.
    const dragDx = aimCurrentMousePos.x - aimStartMousePos.x;
    const dragDy = aimCurrentMousePos.y - aimStartMousePos.y;

    // The shot vector (vx, vy) should point from the cue ball towards where the mouse ended relative to the start.
    // Since we drag *back* to set power/direction, the resulting velocity is proportional to (-dragDx, -dragDy).
    const targetVx = -dragDx;
    const targetVy = -dragDy;

    // Calculate effective power (magnitude of drag)
    const dragMagnitude = Math.sqrt(dragDx * dragDx + dragDy * dragDy);

    // Scale the shot strength: Max power limited by magnitude, but ensure a minimum speed if dragged far enough.
    let powerFactor = Math.min(100, dragMagnitude / 30); // Capping max visible force factor
    powerFactor = Math.max(0.5, powerFactor * 0.8); // Minimum shot strength

    // Apply the calculated velocity scaled by the power factor
    const finalVx = targetVx * powerFactor;
    const finalVy = targetVy * powerFactor;


    // Execute Shot!
    window.sim.shoot(finalVx, finalVy);

    isAiming = false;
    aimStartMousePos = {x: 0, y: 0};
    aimCurrentMousePos = {x: 0, y: 0};
    render(); // Clear aiming line
});


// --- Control Button Listeners ---

document.getElementById('resetButton').addEventListener('click', () => {
    if (animationFrameId) {
        cancelAnimationFrame(animationFrameId);
        gameIsRunning = false;
        document.getElementById('pauseResumeButton').disabled = true;
    }
    window.sim.reset();
    render(); // Initial render of the rack setup
});

// Placeholder for a "Start Shot" button to allow manual triggering after reset
// For simplicity in this single file structure, we'll let the first click on cue ball handle shooting.
const startShotButton = document.createElement('button');
startShotButton.textContent = 'Click White Ball (Cue)';
startShotButton.id = 'shotTrigger';

document.getElementById('controls').appendChild(document.createElement('hr'));
document.getElementById('controls').appendChild(startShotButton);


// Listen for clicks specifically on the cue ball to initiate aiming/shooting process if buttons are used.
canvas.addEventListener('click', (e) => {
    if (isAiming || !gameIsRunning) return;

    const cueBall = balls[cueBallIndex];
    if (cueBall && Math.sqrt((e.offsetX - cueBall.x)**2 + (e.offsetY - cueBall.y)**2) < 50) {
        // Clicking the white ball area should prime the system for aiming (even if mousemove is needed).
        updateStatus("Please begin dragging from this point to aim and shoot.");
        if (!isAiming) { // If we clicked without a prior mousedown event, initiate it.
             isAiming = true;
             aimStartMousePos = getMousePos(e);
             aimCurrentMousePos = aimStartMousePos;
        }
    }
});


document.getElementById('pauseResumeButton').addEventListener('click', () => {
    if (gameIsRunning) {
        window.sim.pause();
    } else if (!window.sim.state().some(b => b.potted)) {
         // Only resume/start if the game is currently stopped and balls aren't all potted
        window.sim.resume(); 
    }
});


// ==============================================
// INITIALIZATION
// ==============================================

// Initial setup: Reset the rack, render the starting position, and start the loop (but wait for player interaction to really 'start').
(function init() {
    window.sim.reset();
    render(); // Draw the initial stationary scene

    // Set initial state of the pause button
    document.getElementById('pauseResumeButton').disabled = true; 

})();


</script>
</body>
</html>
